                && g2_x_1.iter().all(|&b| b == 0)
                && g2_y_0.iter().all(|&b| b == 0)
                && g2_y_1.iter().all(|&b| b == 0);
    
            // Skip this pair if either point is at infinity as it's a no-op
            if g1_is_zero || g2_is_zero {
