            parsed_pairs.push((g1_point, g2_point));
        }
    
        // If all pairs were filtered out, return true (identity element)
        if parsed_pairs.is_empty() {
            return Ok(true);
        }
    
        Ok(pairing_check(&parsed_pairs))
    }
